import React from 'react';
import { render, screen } from '@testing-library/react';
import Card from './Card';

describe('Card', () => {
  test('should render without crashing with medium size props', () => {
    render(
      <Card border="medium" elevated="medium">
        This is a test content to show Card component
      </Card>
    );

    expect(screen.getByText('This is a test content to show Card component')).toBeInTheDocument();
  });

  test('should render without crashing with large size props', () => {
    render(
      <Card border="large" elevated="large">
        This is a test content to show Card component
      </Card>
    );

    expect(screen.getByText('This is a test content to show Card component')).toBeInTheDocument();
  });

  test('should render without crashing with small size props', () => {
    render(
      <Card border="small" elevated="small">
        This is a test content to show Card component
      </Card>
    );

    expect(screen.getByText('This is a test content to show Card component')).toBeInTheDocument();
  });

  test('should render without crashing with medium elevated prop and none border prop', () => {
    render(
      <Card border="none" elevated="medium">
        This is a test content to show Card component
      </Card>
    );

    expect(screen.getByText('This is a test content to show Card component')).toBeInTheDocument();
  });

  test('should render without crashing with minimal elevated prop and medium border prop', () => {
    render(
      <Card border="medium" elevated="minimal">
        This is a test content to show Card component
      </Card>
    );

    expect(screen.getByText('This is a test content to show Card component')).toBeInTheDocument();
  });

  test('should render without crashing with xlarge elevated prop and medium border prop', () => {
    render(
      <Card border="medium" elevated="xlarge">
        This is a test content to show Card component
      </Card>
    );

    expect(screen.getByText('This is a test content to show Card component')).toBeInTheDocument();
  });
});
